@Component("fXDeal-entity-projector")
public class FXDealEntityProjector implements EntityProjector<FXDeal>{
		
	// core constructor
	public FXDealEntityProjector(ProjectorRegistry registry,
										FXDealRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<FXDeal> getEntityClass() {
		return FXDeal.class;
	}

    /*
	 * Insert a FXDeal
	 * 
     * @param	entity FXDeal
     */
    public FXDeal create( FXDeal entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a FXDeal
	 * 
     * @param	entity FXDeal
     */
    public FXDeal update( FXDeal entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a FXDeal
	 * 
     * @param	id		UUID
     */
    public FXDeal delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    FXDeal entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Quote
     * 
     * @param	parentId	UUID
     * @param	assignment 	FXQuote 
     * @return	FXDeal
     */
    public FXDeal assignQuote( UUID parentId, FXQuote assignment ) {
	    LOGGER.info("assigning Quote as " + assignment.toString() );

	    FXDeal parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( FXQuote.class, assignment.getFXQuoteId());

	    // ------------------------------------------
		// assign the Quote to the parent entity
		// ------------------------------------------ 
	    parentEntity.setQuote( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Quote
	 * 
	 * @param	parentId		UUID
	 * @return	FXDeal
	 */
	public FXDeal unAssignQuote( UUID parentId ) {
		FXDeal parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Quote on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Quote on the parent entithy
		// ------------------------------------------     
	    parentEntity.setQuote(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the PaymentOrders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	FXDeal
     */
    public FXDeal addToPaymentOrders( UUID parentId, PaymentOrder addTo ) {
	    LOGGER.info("handling AssignPaymentOrdersToFXDealEvent - " );
	    
	    FXDeal parentEntity = repository.findById(parentId).get();
	    PaymentOrder child = registry.project( PaymentOrder.class, addTo.getPaymentOrderId());
	    
	    parentEntity.getPaymentOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the PaymentOrders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	FXDeal
     */
	public FXDeal removeFromPaymentOrders( UUID parentId, PaymentOrder removeFrom ) {
	    LOGGER.info("handling RemovePaymentOrdersFromFXDealEvent " );
	
	    FXDeal parentEntity = repository.findById(parentId).get();
	    PaymentOrder child = registry.project( PaymentOrder.class, removeFrom.getPaymentOrderId());
	    
	    parentEntity.getPaymentOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the FXDeal via an FindFXDealQuery
     * @return 	query	FindFXDealQuery
     */
    @SuppressWarnings("unused")
    public FXDeal find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a FXDeal - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all FXDeals
     *
     * @param	query	FindAllFXDealQuery 
     * @return 	List<FXDeal> 
     */
    @SuppressWarnings("unused")
    public List<FXDeal> findAll( FindAllFXDealQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all FXDeal - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final FXDealRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(FXDealEntityProjector.class.getName());

}
